    "VariableDeclaration",
    "ExpressionStatement",
    "ReturnStatement",
    "ThrowStatement",
    "ExportDefaultDeclaration",
    "ExportNamedDeclaration",
    "ClassProperty",
    "PropertyDefinition",
    "ClassPrivateProperty",
    "IfStatement",
    "ForStatement",
    "ForOfStatement",
    "ForInStatement",
    "WhileStatement",
    "DoWhileStatement",
    "SwitchStatement",
    "BlockStatement",
])

