    if (n.type === "Identifier") return n.name === "undefined"
    if (n.type === "NullLiteral") return true
    return n.type === "Literal" && n.value === null
}

/** True when a string logPath value points at an absolute (or UNC) location. */
const isAbsoluteLogPath = (value: string): boolean =>
    value.startsWith("/") || value.startsWith("\\")

/**
 * Decides whether the `fileLoggerOptions` argument of a `new FileLogger(...)`
 * call warrants a warning. `logPath` lives in the second constructor argument.
 */
const shouldWarn = (node: NewExpression): boolean => {
    const optionsArg = node.arguments[1]

    // No options argument at all → default log path (relative to cwd).
    if (optionsArg === undefined) return true

    // `undefined` / `null` options → default log path.
    if (isNullish(optionsArg)) return true

    // Anything other than an inline object literal (a variable, call, etc.)
    // cannot be inspected statically — leave it alone.
    if (optionsArg.type !== "ObjectExpression") return false

    let hasSpread = false
    for (const prop of optionsArg.properties) {
        if (prop.type === "SpreadElement" || prop.type === "SpreadProperty") {
            hasSpread = true
            continue
        }
        if (prop.type !== "Property" && prop.type !== "ObjectProperty") {
            continue
        }
        const key = prop.key
        const keyName =
            key.type === "Identifier"
                ? key.name
                : key.type === "StringLiteral" || key.type === "Literal"
                  ? String(key.value)
                  : null
        if (keyName !== "logPath") continue

        const value = prop.value

        // Explicit `logPath: undefined | null` → default log path.
        if (isNullish(value)) return true

        // Explicit string literal → warn only when it is not absolute.
        if (value.type === "StringLiteral" || value.type === "Literal") {
            const raw = value.value
            if (typeof raw === "string") return !isAbsoluteLogPath(raw)
        }

        // Non-literal expression (e.g. `path.resolve(...)`) → cannot tell.
        return false
    }

    // No explicit `logPath`. A lone spread could carry it, so we can only be
    // sure the path is missing when there is no spread at all.
    return !hasSpread
}

/** Walks up to the closest statement-position ancestor of `path`. */
const findEnclosingStatement = (path: ASTPath): Node => {
    let current: ASTPath | null = path
    while (current) {
        if (STATEMENT_TYPES.has(current.node.type)) return current.node
        current = current.parent
    }
    return path.node
}

